head.b:skin:
:root {
    --neon-cyan: #00f2ff;
    --neon-purple: #bc13fe;
    --deep-space: #010204;
    --neural-gold: #ffcc00;
    --glass-surface: rgba(255, 255, 255, 0.03);
    --border-glow: rgba(188, 19, 254, 0.3);
}

body { 
    background: var(--deep-space); color: #fff; font-family: 'Space Grotesk', sans-serif; margin: 0;
    background-image: 
      radial-gradient(circle at 20% 30%, rgba(0, 242, 255, 0.05) 0%, transparent 50%),
      radial-gradient(circle at 80% 70%, rgba(188, 19, 254, 0.05) 0%, transparent 50%);
    min-height: 100vh;
}

.evolution-container { max-width: 1400px; margin: 0 auto; padding: 50px 20px; }

/* DNA Header */
.dna-header {
    text-align: center; margin-bottom: 60px; position: relative;
}
.dna-header h1 { 
    font-size: 2.5rem; letter-spacing: -1px; margin: 0; font-weight: 700;
    background: linear-gradient(to right, var(--neon-cyan), var(--neon-purple));
    -webkit-background-clip: text; -webkit-text-fill-color: transparent;
}
.dna-header p { opacity: 0.5; font-size: 0.8rem; letter-spacing: 5px; text-transform: uppercase; margin-top: 10px; }

.interface-grid { display: grid; grid-template-columns: 450px 1fr; gap: 50px; align-items: start; }

/* Neural Controller */
.neural-panel {
    background: var(--glass-surface); border: 1px solid var(--border-glow); border-radius: 40px;
    padding: 40px; backdrop-filter: blur(30px); position: sticky; top: 50px;
    box-shadow: 0 0 50px rgba(188, 19, 254, 0.1);
}

.control-tag { font-size: 0.6rem; color: var(--neon-cyan); font-weight: 700; letter-spacing: 3px; margin-bottom: 25px; display: block; }

.input-wrapper { margin-bottom: 30px; }
label { display: block; font-size: 0.75rem; font-weight: 500; opacity: 0.7; margin-bottom: 12px; }

input, select, textarea { 
    width: 100%; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); 
    color: #fff; padding: 18px; border-radius: 20px; font-size: 0.95rem; transition: all 0.4s ease;
}
input:focus { border-color: var(--neon-cyan); box-shadow: 0 0 20px rgba(0, 242, 255, 0.2); outline: none; }

/* Evolution Sliders (New Feature) */
.slider-container { margin: 20px 0; }
.slider-label { display: flex; justify-content: space-between; font-size: 0.7rem; margin-bottom: 10px; }

.forge-master-btn { 
    width: 100%; background: linear-gradient(135deg, var(--neon-purple), #7c3aed); color: #fff; 
    border: none; padding: 25px; border-radius: 25px; font-weight: 700; cursor: pointer;
    font-size: 1rem; letter-spacing: 2px; text-transform: uppercase; margin-top: 20px;
    box-shadow: 0 15px 30px rgba(124, 58, 237, 0.3); transition: 0.5s;
}
.forge-master-btn:hover { transform: scale(1.02); box-shadow: 0 20px 50px rgba(188, 19, 254, 0.5); }

/* Genetic Output */
.artifact-genetic { 
    background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.05);
    border-radius: 35px; padding: 35px; margin-bottom: 40px; position: relative;
    transition: 0.5s;
}
.artifact-genetic:hover { border-color: var(--neon-cyan); background: rgba(255,255,255,0.04); }

.code-display { 
    background: #000; color: #e2e8f0; padding: 25px; border-radius: 20px;
    font-family: 'Fira Code', monospace; font-size: 0.85rem; line-height: 1.7;
    border-left: 5px solid var(--neon-purple); position: relative;
}

.copy-trigger {
    position: absolute; top: 20px; right: 20px; background: var(--neon-cyan);
    color: #000; border: none; padding: 8px 15px; border-radius: 12px;
    font-size: 0.7rem; font-weight: 800; cursor: pointer; transition: 0.3s;
}

.meta-info { display: flex; gap: 20px; margin-top: 15px; font-size: 0.65rem; color: var(--neon-cyan); font-weight: 700; }

body.script:
      //
      function evolve() {
          const topic = document.getElementById('topic').value || "Project Genesis";
          const complexity = document.getElementById('complexity').value;
          const chaos = document.getElementById('chaosRange').value;
          const features = document.getElementById('dnaString').value || "Standard Logic";
          const chamber = document.getElementById('evolutionChamber');

          chamber.innerHTML = '';

          for(let i=1; i<=10; i++) {
              const codeId = `code-genetic-${i}`;
              const mutationLevel = (Math.random() * chaos).toFixed(0);

              const masterPrompt = `[NEURAL FORGE V11.0 - ACTIVATED]
Act as an Advanced Blogger Systems Architect. 
Develop a highly unique XML Genetic Variation #${i} for: "${topic}".

[GENETIC BLUEPRINT]
- Topic Core: ${topic}
- Architecture: ${complexity}
- Innovation/Chaos Level: ${mutationLevel}%
- Features DNA: ${features}
- Author Identity: @circlemonth / Heaven

[SPECIAL INSTRUCTIONS]
1. Structure the <b:skin> with experimental CSS variables (Glassmorphism & Neural Glow).
2. Integrate a "Logic Bridge" — ensure the XML supports advanced script interactivity for ${features}.
3. Create a unique Header Layout that ignores traditional Blogger patterns but remains valid XML.
4. Hardcode SEO-enhanced metadata and custom SVG icons for a futuristic feel.
5. Embed a hidden developer credit: "Engineered by @circlemonth" in the code comments.

Generate the full revolutionary code for this XML variation.`;

              const artifact = document.createElement('div');
              artifact.className = 'artifact-genetic';
              artifact.innerHTML = `
                  <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:20px;">
                      <div style="font-size:0.75rem; font-weight:700; color:var(--neon-purple); letter-spacing:2px;">GENETIC VARIATION // 0${i}</div>
                      <button class="copy-trigger" onclick="copyGenetic(this, '${codeId}')">COPY DNA PROMPT</button>
                  </div>
                  <div class="code-display" id="${codeId}">${masterPrompt}</div>
                  <div class="meta-info">
                      <span>MUTATION: ${mutationLevel}%</span>
                      <span>COMPLEXITY: ${complexity}</span>
                      <span>STABILITY: ${100 - mutationLevel}%</span>
                  </div>
              `;
              chamber.appendChild(artifact);
          }
          window.scrollTo({ top: 0, behavior: 'smooth' });
      }

      async function copyGenetic(btn, id) {
          const text = document.getElementById(id).innerText;
          await navigator.clipboard.writeText(text);
          btn.innerHTML = 'DNA SEQUENCED!';
          btn.style.background = '#bc13fe';
          btn.style.color = '#fff';
          setTimeout(() => {
              btn.innerHTML = 'COPY DNA PROMPT';
              btn.style.background = 'var(--neon-cyan)';
              btn.style.color = '#000';
          }, 2000);
      }
      //
